for i in range(batch):
          activity.heartbeat({"done": i})              # 每批心跳一次
      return batch

  @workflow.defn
  class IngestWorkflow:
      def __init__(self):
          self.approved = False

      @workflow.signal
      def approve(self, ok: bool):                     # 外部调用 handle.signal(...)
          self.approved = ok

      @workflow.query
      def progress(self) -> str:
          return "waiting-approval" if not self.approved else "running"

      @workflow.run
      async def run(self, doc_id: str) -> str:
          try:
              await workflow.execute_activity(
                  embed_batch, args=[doc_id, 10],
                  start_to_close_timeout=timedelta(minutes=5),
                  heartbeat_timeout=timedelta(seconds=30),
                  retry_policy=RETRY)
          except ApplicationError as e:
              if e.non_retryable:
                  raise
          await workflow.wait_condition(lambda: self.approved, timeout=timedelta(hour
  s=24))
          return "done"


 记牢start_to_close_timeout 必设；重试默认起始 1s、系数 2.0、次数无限——不设超时
等于无限重试。


  Ⅲ 先把一条中文查询搜对


默认分词会把词切成单字


  单节点用 Docker 起，9200 是 REST 端口。建索引用 PUT /<index> ，重点是 settings
（分片数、刷新间隔）与 mappings （字段类型与分词器）。中文一定要装 analysis-ik 插
件，否则默认分词会把「向量库选型」切成单字。写入用 _bulk （NDJSON、每行一个
JSON、最后一行必须有换行），查询用 _search 的 Query DSL。





